/**
 * Base64-encoded Noto Sans Ethiopic TTF bytes, generated once from the
 * vendored .ttf files in this directory (see OFL.txt for license terms).
 * Embedded as plain string constants rather than read from disk at
 * runtime: this module gets compiled two different ways depending on which
 * spec imports it — CommonJS everywhere the app actually runs, and native
 * ESM inside the pdf-smoke Jest project (which needs a real `import()` of
 * ESM-only puppeteer — see jest config comments on that spec). `__dirname`
 * and `import.meta` each break one of those two compile targets; a plain
 * string constant breaks neither, and it also means no build step has to
 * copy binary assets into dist/.
 *
 * Regenerate from the vendored .ttf files if they ever change:
 *   node -e "console.log(require('fs').readFileSync('NotoSansEthiopic-Regular.ttf').toString('base64'))"
 */
export const NOTO_SANS_ETHIOPIC_REGULAR_BASE64 =
  '';

export const NOTO_SANS_ETHIOPIC_BOLD_BASE64 =
  '';
